('w:calvo','b2','calvo','прил.','лысый','Ficou calvo muito cedo, aos trinta anos.','Он облысел очень рано, в тридцать лет.','','B2','B1',190,'лисий','Він облисів дуже рано, у тридцять років.',''),
('w:camomila','b2','a camomila','сущ.','ромашка','Um chá de camomila ajuda a dormir.','Ромашковый чай помогает уснуть.','','B2','B8',191,'ромашка','Ромашковий чай допомагає заснути.',''),
('w:candidatar-se','b2','candidatar-se','глаг.','подавать заявку, баллотироваться','Candidatou-se a uma bolsa de estudo em Coimbra.','Он подал заявку на стипендию в Коимбре.','candidatar-se a','B2','B3',192,'подавати заявку, балотуватися','Він подав заявку на стипендію в Коїмбрі.','candidatar-se a'),
('w:candidato','b2','o candidato','сущ.','кандидат, соискатель','Havia trinta candidatos para uma única vaga.','На одно место было тридцать кандидатов.','','B2','B3',193,'кандидат, здобувач','На одне місце було тридцять кандидатів.',''),
('w:cansar','b2','cansar','глаг.','утомлять','Subir tantas escadas cansa qualquer pessoa, mesmo em boa forma.','Столько ступенек утомят кого угодно, даже в хорошей форме.','','B2','B6',194,'утомлювати','Стільки сходинок утомлять будь-кого, навіть у добрій формі.',''),
('w:cantarolar','b2','cantarolar','глаг.','напевать','Ia a cantarolar uma canção antiga pelo caminho.','Он шёл по дороге, напевая старую песню.','','B2','B4',195,'наспівувати','Він ішов дорогою, наспівуючи стару пісню.',''),
('w:capacho','b2','o capacho','сущ.','коврик у двери','Deixei a chave debaixo do capacho, como combinámos.','Я оставил ключ под ковриком, как договаривались.','','B2','B2',196,'килимок біля дверей','Я лишив ключ під килимком, як домовлялися.',''),
('w:capela','b2','a capela','сущ.','часовня','Há uma capela pequena no alto do monte.','На вершине холма стоит маленькая часовня.','','B2','B2',197,'каплиця','На вершині пагорба стоїть маленька каплиця.',''),
('w:caroço','b2','o caroço','сущ.','косточка (плода)','Cuidado com o caroço da azeitona, parte-se um dente.','Осторожно с оливковой косточкой — так и зуб сломать недолго.','','B2','B8',198,'кісточка (плоду)','Обережно з оливковою кісточкою — так і зуб зламати недовго.',''),
('w:casca','b2','a casca','сущ.','кожура, скорлупа, корка','Descasque a laranja e guarde a casca.','Очистите апельсин и сохраните кожуру.','','B2','B8',199,'шкірка, шкаралупа','Обчистіть апельсин і збережіть шкірку.','')
insert into public.pt_words (id, deck_id, word, pos, ru, ex, exru, note, level, tema, sort, uk, exuk, noteuk) values
('w:cativante','b2','cativante','прил.','располагающий, обаятельный','Tem um sorriso cativante e uma voz calma.','У неё обаятельная улыбка и спокойный голос.','','B2','B1',200,'чарівливий, приязний','У неї чарівлива усмішка і спокійний голос.',''),
('w:católico','b2','o católico','сущ.','католик','A maioria dos portugueses é católica, embora poucos vão à missa.','Большинство португальцев — католики, хотя в церковь ходят немногие.','','B2','B1',201,'католик','Більшість португальців — католики, хоча до церкви ходять небагато.',''),
('w:cegonha','b2','a cegonha','сущ.','аист','As cegonhas fazem ninho nas chaminés antigas.','Аисты вьют гнёзда на старых трубах.','','B2','B2',202,'лелека','Лелеки в’ють гнізда на старих димарях.',''),
('w:censura','b2','a censura','сущ.','цензура; порицание','Durante a ditadura havia censura na imprensa.','Во время диктатуры в прессе была цензура.','','B2','B9',203,'цензура; осуд','За часів диктатури в пресі була цензура.',''),
('w:centeio','b2','o centeio','сущ.','рожь','Prefiro pão de centeio ao pão branco.','Я предпочитаю ржаной хлеб белому.','','B2','B8',204,'жито','Я віддаю перевагу житньому хлібу перед білим.',''),
('w:cerne','b2','o cerne','сущ.','суть, ядро','Chegámos finalmente ao cerne da questão ao fim de duas horas.','Через два часа мы наконец добрались до сути вопроса.','','B2','A8',205,'суть, осердя','За дві години ми нарешті дісталися суті питання.',''),
('w:cervejaria','b2','a cervejaria','сущ.','пивной ресторан','Jantámos marisco numa cervejaria perto do Cais.','Мы поужинали морепродуктами в пивной у причала.','В Португалии это ещё и ресторан морепродуктов','B2','B8',206,'пивний ресторан','Ми повечеряли морепродуктами в пивній біля причалу.','У Португалії це ще й ресторан морепродуктів'),
('w:chefiar','b2','chefiar','глаг.','возглавлять','Ela chefia o departamento há três anos.','Она возглавляет отдел уже три года.','','B2','B3',207,'очолювати','Вона очолює відділ уже три роки.',''),
('w:chinelo','b2','o chinelo','сущ.','тапок, шлёпанец','Anda de chinelos por casa o dia todo.','Он весь день ходит по дому в тапках.','','B2','B7',208,'капець, шльопанець','Він цілий день ходить по дому в капцях.',''),
('w:chocar','b2','chocar','глаг.','шокировать; сталкиваться','A notícia chocou toda a gente na aldeia.','Новость шокировала всех в деревне.','','B2','B1',209,'шокувати; зіштовхуватися','Новина шокувала всіх у селі.',''),
('w:chouriço','b2','o chouriço','сущ.','колбаса чурису','O cozido leva chouriço, couve e batata.','В кожиду идут чурису, капуста и картофель.','Копчёная свиная колбаса, основа многих блюд','B2','B8',210,'ковбаса чурису','У кожиду йдуть чурису, капуста й картопля.','Копчена свиняча ковбаса, основа багатьох страв'),
('w:chuvoso','b2','chuvoso','прил.','дождливый','O outono no Minho é bastante chuvoso.','Осень в Минью довольно дождливая.','','B2','B2',211,'дощовий','Осінь у Міню доволі дощова.',''),
('w:cicatrizar','b2','cicatrizar','глаг.','заживать','A ferida cicatrizou em pouco mais de uma semana.','Рана зажила чуть больше чем за неделю.','','B2','B6',212,'загоюватися','Рана загоїлася трохи більше ніж за тиждень.',''),
('w:ciclista','b2','o ciclista','сущ.','велосипедист','Os ciclistas têm uma faixa própria nesta avenida.','У велосипедистов на этом проспекте своя полоса.','','B2','B5',213,'велосипедист','У велосипедистів на цьому проспекті своя смуга.',''),
('w:cidadania','b2','a cidadania','сущ.','гражданство','Pediu a cidadania portuguesa depois de cinco anos.','Он подал на португальское гражданство через пять лет.','','B2','B1',214,'громадянство','Він подав на португальське громадянство через п’ять років.',''),
('w:cigano','b2','o cigano','сущ.','цыган','Havia uma feira de ciganos à saída da vila.','На выезде из городка была цыганская ярмарка.','','B2','B1',215,'циган','На виїзді з містечка був циганський ярмарок.',''),
('w:circulação','b2','a circulação','сущ.','движение; кровообращение','A circulação está cortada na ponte até domingo.','Движение по мосту перекрыто до воскресенья.','','B2','B5',216,'рух; кровообіг','Рух мостом перекрито до неділі.',''),
('w:cláusula','b2','a cláusula','сущ.','пункт договора','Leia com atenção a cláusula sobre o depósito.','Внимательно прочитайте пункт о залоге.','','B2','B9',217,'пункт договору','Уважно прочитайте пункт про заставу.',''),
('w:colaborador','b2','o colaborador','сущ.','сотрудник','A empresa tem cinquenta colaboradores em Lisboa.','В компании пятьдесят сотрудников в Лиссабоне.','','B2','B3',218,'працівник компанії','У компанії п’ятдесят працівників у Лісабоні.',''),
('w:colcha','b2','a colcha','сущ.','покрывало','Pôs uma colcha grossa na cama por causa do frio.','Она постелила толстое покрывало из-за холода.','','B2','B2',219,'покривало','Вона застелила товсте покривало через холод.',''),
('w:colorido','b2','colorido','прил.','цветной, яркий','O mercado estava colorido e cheio de gente.','Рынок был ярким и полным людей.','','B2','A6',220,'барвистий','Ринок був барвистий і повний людей.',''),
('w:comemoração','b2','a comemoração','сущ.','празднование','Houve comemorações em toda a cidade nesse dia.','В тот день по всему городу были празднования.','','B2','B4',221,'святкування','Того дня по всьому місту були святкування.',''),
('w:comentar','b2','comentar','глаг.','комментировать, высказываться','Prefiro não comentar o assunto por agora.','Пока я предпочту не комментировать этот вопрос.','','B2','A8',222,'коментувати, висловлюватися','Поки що я волію не коментувати це питання.',''),
('w:comerciante','b2','o comerciante','сущ.','торговец, коммерсант','Os comerciantes da rua pediram mais segurança.','Торговцы с этой улицы попросили усилить охрану.','','B2','B7',223,'торговець, комерсант','Торговці з цієї вулиці попросили посилити охорону.',''),
('w:comodidade','b2','a comodidade','сущ.','удобство','O quarto é pequeno, mas tem todas as comodidades.','Номер маленький, но со всеми удобствами.','','B2','A7',224,'зручність','Номер маленький, але з усіма зручностями.',''),
('w:comparecer','b2','comparecer','глаг.','являться, присутствовать','Tem de comparecer no tribunal na quinta-feira.','Вы должны явиться в суд в четверг.','','B2','A2',225,'з’являтися за викликом','Ви маєте з’явитися до суду в четвер.',''),
('w:competitivo','b2','competitivo','прил.','конкурентный; соревновательный','O preço deles é muito competitivo para a qualidade oferecida.','Их цена очень выгодна для такого качества.','','B2','A7',226,'конкурентний','Їхня ціна дуже вигідна як на таку якість.',''),
('w:complicação','b2','a complicação','сущ.','осложнение','Houve uma complicação depois da operação e ficou mais dias.','После операции возникло осложнение, и он пролежал дольше.','','B2','B6',227,'ускладнення','Після операції виникло ускладнення, і він пролежав довше.',''),
('w:compositor','b2','o compositor','сущ.','композитор','O compositor escreveu a música em duas semanas.','Композитор написал музыку за две недели.','','B2','B4',228,'композитор','Композитор написав музику за два тижні.',''),
('w:conceder','b2','conceder','глаг.','предоставлять, даровать','O banco concedeu-lhes um empréstimo a dez anos.','Банк предоставил им кредит на десять лет.','','B2','B9',229,'надавати (офіційно)','Банк надав їм кредит на десять років.',''),
('w:concorrente','b2','o concorrente','сущ.','конкурент; участник конкурса','O nosso maior concorrente abriu loja ao lado.','Наш главный конкурент открыл магазин рядом.','','B2','B4',230,'конкурент; учасник конкурсу','Наш головний конкурент відкрив магазин поруч.',''),
('w:concorrer','b2','concorrer','глаг.','участвовать в конкурсе; конкурировать','Concorreu a uma vaga na universidade do Porto.','Он участвовал в конкурсе на место в университете Порту.','','B2','B4',231,'брати участь у конкурсі; змагатися','Він брав участь у конкурсі на місце в університеті Порту.',''),
('w:concretizar','b2','concretizar','глаг.','осуществлять','Finalmente concretizámos o sonho de comprar casa.','Мы наконец осуществили мечту купить дом.','','B2','A1',232,'втілювати','Ми нарешті втілили мрію купити дім.',''),
('w:condenar','b2','condenar','глаг.','осуждать, приговаривать','O tribunal condenou-o a dois anos de prisão.','Суд приговорил его к двум годам заключения.','','B2','B9',233,'засуджувати','Суд засудив його до двох років ув’язнення.',''),
('w:confeitaria','b2','a confeitaria','сущ.','лавка со сладостями','Comprámos os bolos naquela confeitaria antiga junto ao rio.','Мы купили пирожные в той старой лавке у реки.','Кофе и завтрак — скорее в pastelaria','B2','B8',234,'крамниця солодощів','Ми купили тістечка в тій старій крамниці біля річки.','Кава і сніданок — радше в pastelaria'),
('w:conferir','b2','conferir','глаг.','сверять, проверять','Confira o troco antes de sair da loja.','Проверьте сдачу, прежде чем выйти из магазина.','','B2','A8',235,'звіряти, перевіряти','Перевірте решту, перш ніж вийти з магазину.',''),
('w:confidência','b2','a confidência','сущ.','доверительное признание','Fez-me uma confidência que prometi não contar a ninguém.','Он доверил мне тайну, которую я обещал никому не рассказывать.','Обычно во мн. ч.: fazer confidências a alguém','B2','A8',236,'довірливе зізнання','Він довірив мені таємницю, яку я обіцяв нікому не розповідати.','Зазвичай у множині: fazer confidências a alguém'),
('w:configuração','b2','a configuração','сущ.','настройка, наладка','A configuração do computador demorou mais do que esperávamos.','Настройка компьютера заняла больше времени, чем мы ожидали.','Настройки в телефоне — as definições, а не as configurações','B2','B3',237,'налаштування, наладка','Налаштування комп’ютера тривало довше, ніж ми очікували.','Налаштування в телефоні — as definições'),
('w:configurar','b2','configurar','глаг.','настраивать','O técnico configurou a rede sem fios em dez minutos.','Мастер настроил беспроводную сеть за десять минут.','','B2','B3',238,'налаштовувати','Майстер налаштував бездротову мережу за десять хвилин.',''),
('w:confortar','b2','confortar','глаг.','утешать, ободрять','As palavras da avó confortaram-me naquele dia difícil.','Слова бабушки утешили меня в тот трудный день.','','B2','B1',239,'утішати, підбадьорювати','Слова бабусі втішили мене того важкого дня.',''),
('w:confronto','b2','o confronto','сущ.','столкновение, противостояние','Houve um confronto entre adeptos à saída do estádio.','У выхода со стадиона произошло столкновение между болельщиками.','','B2','A9',240,'зіткнення, протистояння','Біля виходу зі стадіону сталося зіткнення між уболівальниками.',''),
('w:confundir','b2','confundir','глаг.','путать, сбивать с толку','Confundo sempre estas duas palavras por causa do som.','Я всегда путаю эти два слова из-за звучания.','confundir-se — спутать одно с другим, обознаться','B2','A8',241,'плутати, збивати з пантелику','Я завжди плутаю ці два слова через звучання.','confundir-se — сплутати одне з іншим, обізнатися'),
('w:cônjuge','b2','o cônjuge','сущ.','супруг, супруга','O formulário pede também os dados do cônjuge.','В бланке нужно указать ещё и данные супруга.','Слово из документов; в речи — o marido, a mulher','B2','B1',242,'чоловік або дружина (у документах)','У бланку треба вказати ще й дані подружжя.','Слово з документів; у мовленні — o marido, a mulher'),
('w:conquista','b2','a conquista','сущ.','завоевание, достижение','O direito a férias pagas foi uma conquista importante.','Право на оплачиваемый отпуск стало важным завоеванием.','','B2','A7',243,'здобуток, завоювання','Право на оплачувану відпустку стало важливим здобутком.',''),
('w:consenso','b2','o consenso','сущ.','единое мнение, консенсус','Depois de muita discussão, chegámos finalmente a um consenso.','После долгого спора мы наконец пришли к общему мнению.','','B2','A8',244,'спільна думка, консенсус','Після довгої суперечки ми нарешті дійшли спільної думки.',''),
('w:conservação','b2','a conservação','сущ.','сохранение, сбережение','O museu gasta muito dinheiro na conservação dos quadros.','Музей тратит много денег на сохранение картин.','','B2','B2',245,'збереження','Музей витрачає багато грошей на збереження картин.',''),
('w:conservador','b2','o conservador','сущ.','консерватор','Os conservadores votaram contra a mudança da lei.','Консерваторы проголосовали против изменения закона.','Как прилагательное — консервативный, осторожный','B2','B9',246,'консерватор','Консерватори проголосували проти зміни закону.','Як прикметник — консервативний, обережний'),
('w:constituição','b2','a constituição','сущ.','конституция','A Constituição portuguesa garante o direito à saúde.','Португальская конституция гарантирует право на охрану здоровья.','Также состав, образование: a constituição de uma equipa','B2','B9',247,'конституція','Португальська конституція гарантує право на охорону здоров’я.','Також склад, утворення: a constituição de uma equipa'),
('w:construtivo','b2','construtivo','прил.','конструктивный','A reunião foi curta, mas muito construtiva para todos.','Встреча была короткой, но очень конструктивной для всех.','','B2','A7',248,'конструктивний','Зустріч була коротка, але дуже конструктивна для всіх.',''),
